import{_ as s,o as i,c as a,a2 as t}from"./chunks/framework.CpZKh-tG.js";const k=JSON.parse('{"title":"ADR-071 — Consolidate e2e workflows: docker-e2e becomes the canonical Playwright gate; delete e2e.yml","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-071.md","filePath":"adr/ADR-071.md"}'),o={name:"adr/ADR-071.md"};function n(r,e,l,h,d,c){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="adr-071-—-consolidate-e2e-workflows-docker-e2e-becomes-the-canonical-playwright-gate-delete-e2e-yml" tabindex="-1">ADR-071 — Consolidate e2e workflows: docker-e2e becomes the canonical Playwright gate; delete e2e.yml <a class="header-anchor" href="#adr-071-—-consolidate-e2e-workflows-docker-e2e-becomes-the-canonical-playwright-gate-delete-e2e-yml" aria-label="Permalink to &quot;ADR-071 — Consolidate e2e workflows: docker-e2e becomes the canonical Playwright gate; delete e2e.yml&quot;">​</a></h1><blockquote><p>Status · Accepted Date · 2026-05-30 Closes into · <code>.github/workflows/docker-e2e.yml</code> (modifications), <code>.github/workflows/preview.yml</code> (workflow_run change), removal of <code>.github/workflows/e2e.yml</code> Related ADRs · ADR-014 (CI pipeline), ADR-015 (Playwright e2e + adapter-static), ADR-066 (docker-e2e — supersedes its trigger surface + relationship sections), ADR-070 (docs/app deploy split) Closes follow-ups · perf-umbrella #95 W7 loose-thread closeout</p></blockquote><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>When <code>docker-e2e.yml</code> shipped (ADR-066, May 22), it was designed to coexist alongside <code>e2e.yml</code>:</p><ul><li><code>e2e.yml</code> ran Playwright against <code>vite preview</code> — protecting the GitHub Pages deploy target (SvelteKit&#39;s Node preview server is the closest local approximation to how GH Pages serves the bundle).</li><li><code>docker-e2e.yml</code> ran Playwright against the docker-compose nginx stack — protecting the eventual VPS deploy target (RFC-024).</li></ul><p>ADR-066 was explicit about why two separate workflows: cost discipline (Svelte-only PRs shouldn&#39;t pay the docker build tax), failure attribution clarity (a red docker-e2e ≡ a docker-shape regression, not a Svelte regression), and minimum-duplication of test work (docker-e2e was scoped desktop-only because the nginx contract is viewport-independent; mobile-chromium stayed in e2e.yml).</p><p><strong>Two things have changed since.</strong></p><h3 id="change-1-—-w7-sharding-broke-adr-066-s-desktop-only-invariant" tabindex="-1">Change 1 — W7 sharding broke ADR-066&#39;s &quot;desktop-only&quot; invariant <a class="header-anchor" href="#change-1-—-w7-sharding-broke-adr-066-s-desktop-only-invariant" aria-label="Permalink to &quot;Change 1 — W7 sharding broke ADR-066&#39;s &quot;desktop-only&quot; invariant&quot;">​</a></h3><p>When the docker-e2e mobile leg started touching the 30-min cap, W7 (#277) sharded mobile-chromium into 2 parallel legs to bring per-leg runtime back under control:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">matrix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">desktop-chromium</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      shard</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;1/1&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mobile-chromium</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      shard</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;1/2&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mobile-chromium</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      shard</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;2/2&#39;</span></span></code></pre></div><p>This solved the timeout but silently violated ADR-066&#39;s anti-duplication argument: mobile-chromium now runs in <strong>both</strong> workflows. Same specs, same viewport, same browser engine — once against <code>vite preview</code>, once against docker-nginx. The &quot;mobile stays in e2e.yml; docker-e2e is desktop-only to avoid redundant runner cost&quot; balance the ADR struck was already gone before this ADR was filed.</p><h3 id="change-2-—-deployment-topology-reframe" tabindex="-1">Change 2 — deployment-topology reframe <a class="header-anchor" href="#change-2-—-deployment-topology-reframe" aria-label="Permalink to &quot;Change 2 — deployment-topology reframe&quot;">​</a></h3><p>ADR-066 implicitly assumed <strong>two equally-important deploy targets</strong>: GH Pages and the future VPS. In that frame, two e2e workflows protecting two targets was the right shape.</p><p>The current frame is different: <strong>GH Pages is a staging area on the path to VPS, serving the same users</strong>. VPS is the canonical prod target; GH Pages is the transitional fallback. In that frame, only the VPS-shape gate (docker-e2e) protects real prod. The e2e.yml workflow tests <code>vite preview</code>, which:</p><ol><li>Isn&#39;t a deploy target (it&#39;s a Node preview server SvelteKit ships for local development).</li><li>Doesn&#39;t match GH Pages serving either (different MIME handling, different SPA fallback mechanism — vite preview uses SvelteKit&#39;s history-API-aware server; GH Pages uses the <code>404.html</code> redirect trick from ADR-014).</li><li>Was always a <em>proxy</em> for GH Pages testing, never a direct test of it.</li></ol><p>So <code>e2e.yml</code> was protecting a deploy target nobody actually deploys to, using a serving stack nobody actually serves with, and duplicating mobile-chromium coverage that <code>docker-e2e.yml</code> was already providing post-W7.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Delete <code>.github/workflows/e2e.yml</code>. Promote <code>.github/workflows/docker-e2e.yml</code> to the canonical Playwright gate. The PR cost-discipline + failure-attribution arguments from ADR-066 still apply, but the relationship between the two workflows the ADR specified is no longer needed.</strong></p><h3 id="trigger-surface-new" tabindex="-1">Trigger surface (new) <a class="header-anchor" href="#trigger-surface-new" aria-label="Permalink to &quot;Trigger surface (new)&quot;">​</a></h3><p><code>docker-e2e.yml</code> triggers update to absorb e2e.yml&#39;s role:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Chained after CI (was: direct push:main + path-gated PR + dispatch).</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Matches the workflow_run pattern e2e.yml used to use — a cheap CI</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # failure short-circuits the expensive docker build + Playwright run.</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  workflow_run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    workflows</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;CI&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    types</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">completed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    branches</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  workflow_dispatch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # External-state drift catch — moved from e2e.yml. Time chosen to land</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # before EU devs start the day; off-minute (:07) dodges GitHub</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Actions&#39; top-of-hour scheduler contention.</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  schedule</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">cron</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;7 5 * * *&#39;</span></span></code></pre></div><p>PR trigger drops entirely. Per the current frame, <strong>PRs run CI only</strong>. The full Playwright surface runs on main where it&#39;s both required (deploy gate) and cheap-amortised (rare merges vs frequent PR pushes).</p><h3 id="preview-yml-retarget" tabindex="-1">preview.yml retarget <a class="header-anchor" href="#preview-yml-retarget" aria-label="Permalink to &quot;preview.yml retarget&quot;">​</a></h3><p><code>preview.yml</code> was gated on <code>workflow_run: workflows: [&#39;e2e&#39;]</code>. Updates to gate on docker-e2e instead:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  workflow_run</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    workflows</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;docker-e2e&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    types</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">completed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    branches</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Same <code>conclusion == &#39;success&#39;</code> guard pattern; same shared <code>gh-pages-publish</code> concurrency group from ADR-070. The GH Pages app+docs deploy now rides the docker-e2e green signal instead of the e2e green signal. Operationally indistinguishable — same Playwright specs, same pass/fail outcome, just routed through one workflow instead of two.</p><h3 id="what-this-supersedes-in-adr-066" tabindex="-1">What this supersedes in ADR-066 <a class="header-anchor" href="#what-this-supersedes-in-adr-066" aria-label="Permalink to &quot;What this supersedes in ADR-066&quot;">​</a></h3><p>ADR-066&#39;s design intent (a CI gate that asserts the nginx-serving contract) <strong>stands</strong>. What this ADR supersedes:</p><ul><li>The &quot;Trigger surface&quot; section (<code>push: branches: [main]</code> + path-gated <code>pull_request:</code>) is replaced by workflow_run-after-CI + cron + dispatch (no PR trigger).</li><li>The &quot;Why desktop-chromium only&quot; section is no longer in effect — W7 added mobile sharding, and docker-e2e is now the only e2e workflow, so it must cover mobile.</li><li>The &quot;Relationship to existing workflows&quot; three-workflow partition is replaced by a two-workflow partition: <code>ci.yml</code> (cheap gate) + <code>docker-e2e.yml</code> (heavy gate).</li><li>The &quot;Branch protection&quot; path-conditional required-for-merge configuration is moot — PRs don&#39;t run docker-e2e at all under the new shape.</li></ul><p>The rest of ADR-066 (decision to use the docker-compose stack as the validation target, <code>PLAYWRIGHT_BASE_URL</code> env-var override, <code>playwright.config.ts</code> webServer short-circuit, capture-logs-on-failure, GHCR publish on green main) <strong>continues to apply unchanged</strong>.</p><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to &quot;Rationale&quot;">​</a></h2><h3 id="why-now-not-earlier" tabindex="-1">Why now, not earlier <a class="header-anchor" href="#why-now-not-earlier" aria-label="Permalink to &quot;Why now, not earlier&quot;">​</a></h3><p>The ADR-066 design was correct for May 22&#39;s context: GH Pages was the live production target, the docker stack was a future bet, both needed their own e2e gates. Two changes (W7 sharding silently breaking ADR-066&#39;s no-mobile-duplication invariant + the deployment-topology reframe positioning VPS as canonical and GH Pages as transitional) moved the right answer here.</p><p>This ADR isn&#39;t reversing ADR-066; it&#39;s recognising that two changes that both happened independently have moved us past it.</p><h3 id="why-workflow-run-after-ci-on-the-new-docker-e2e" tabindex="-1">Why workflow_run-after-CI on the new docker-e2e <a class="header-anchor" href="#why-workflow-run-after-ci-on-the-new-docker-e2e" aria-label="Permalink to &quot;Why workflow_run-after-CI on the new docker-e2e&quot;">​</a></h3><p>Today docker-e2e fires on <code>push: branches: [main]</code> directly — parallel with CI rather than chained. That made sense when docker-e2e was the secondary gate and CI was the primary. Now that docker-e2e <em>is</em> the gate, the workflow_run pattern e2e.yml pioneered applies: cheap typecheck/lint/unit-test failure short-circuits the expensive docker build + Playwright run. Saves ~15-25 min when CI fails on main; adds ~2-3 min of latency when CI succeeds (which is the common case but matters less because main-push wall-clock is less critical than PR wall-clock).</p><h3 id="why-no-pr-trigger" tabindex="-1">Why no PR trigger <a class="header-anchor" href="#why-no-pr-trigger" aria-label="Permalink to &quot;Why no PR trigger&quot;">​</a></h3><p>Per the current frame, the cost-amortisation argument for PR gates is different than ADR-066 assumed:</p><ul><li>ADR-066: required-for-merge on PRs that touch docker paths, advisory on everything else. Reasoning: catch docker regressions at PR time so they don&#39;t land on main.</li><li>Now: PR feedback should be fast (~3 min CI), main is where the heavy gate runs. Any regression that escapes CI gets caught on the next <code>workflow_run</code>-chained docker-e2e and blocks <code>preview.yml</code> from deploying.</li></ul><p>The &quot;regression hits main but doesn&#39;t deploy&quot; failure mode is acceptable — the deploy gate is what actually matters, and it stays in place via preview.yml&#39;s workflow_run dependency.</p><h3 id="why-keep-the-nightly-cron" tabindex="-1">Why keep the nightly cron <a class="header-anchor" href="#why-keep-the-nightly-cron" aria-label="Permalink to &quot;Why keep the nightly cron&quot;">​</a></h3><p>ADR-066 didn&#39;t carry a cron because external-state-drift wasn&#39;t its concern. e2e.yml had one (catching CDN outages, Wikimedia URL drift). Moving the cron to docker-e2e.yml preserves that protection without adding new infrastructure.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ul><li><strong>Keep both workflows, fix the W7 duplication by dropping mobile from docker-e2e and accepting 30-min mobile-only docker-e2e runtime.</strong> Rejected: returns to the desktop-only/mobile-only split ADR-066 originally chose, but adds back the runtime cliff W7 was solving. And the deployment-topology reframe still leaves e2e.yml protecting a deploy target nobody deploys to.</li><li><strong>Keep both workflows, drop the e2e.yml mobile coverage to dedup with docker-e2e.</strong> Rejected: leaves e2e.yml as a desktop-only workflow protecting <code>vite preview</code>, which is even less useful than today. The remaining problem (vite preview ≠ a real deploy target) doesn&#39;t go away.</li><li><strong>Delete docker-e2e instead, keep e2e.yml.</strong> Rejected: explicitly contradicts ADR-066&#39;s central observation that nginx contract bugs (Cache-Control, CSP, brotli, SPA fallback via <code>try_files</code>) only surface under nginx. e2e.yml against <code>vite preview</code> cannot catch them.</li><li><strong>Run docker-e2e on PRs path-gated to docker paths.</strong> Rejected: per the current frame, PRs run CI only. Path-gated PR triggers add operational complexity (branch-protection path-conditional required-for-merge is a repo-settings concern documented in ADR-066) for marginal value. If a docker-touching PR is going to land on main and trigger workflow_run-chained docker-e2e anyway, the regression is caught one step later but still before deploy.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Positive:</strong></p><ul><li>One canonical Playwright gate instead of two. Mobile-chromium runs once, not twice. Roughly halves the per-push runner-minute cost on main pushes.</li><li>preview.yml deploy gate is consolidated — when it fires, it&#39;s because the workflow that protects prod (docker-e2e) passed. Cleaner mental model.</li><li>PR feedback loop is uncoupled from e2e cost. ~3 min CI gate per PR; main pays the ~17-25 min docker-e2e cost.</li><li>e2e.yml&#39;s nightly external-state-drift catch is preserved on docker-e2e.yml.</li><li>ADR-066&#39;s anti-duplication invariant is restored (mobile-chromium runs once again, just in the surviving workflow).</li></ul><p><strong>Negative:</strong></p><ul><li>The <code>vite preview</code> serving path is no longer tested in CI at all. Counter: it was never a deploy target, GH Pages serving differs from it, and the Playwright specs themselves don&#39;t care which server they hit. If a vite-preview-specific bug ever needs catching, local <code>npm run test:e2e</code> still exercises the path.</li><li>One more documentation update sweep: README badge, AGENTS.md workflow listing, this ADR.</li><li>ADR-066 partial supersession adds historical-context complexity for future readers. Mitigated by the explicit list above of what stands vs what&#39;s superseded.</li></ul><h2 id="decision-status" tabindex="-1">Decision status <a class="header-anchor" href="#decision-status" aria-label="Permalink to &quot;Decision status&quot;">​</a></h2><p><strong>Accepted on 2026-05-30.</strong> Implementation:</p><ul><li><code>.github/workflows/e2e.yml</code> deleted.</li><li><code>.github/workflows/docker-e2e.yml</code>: triggers swapped from push:main + path-gated PR + dispatch to workflow_run-after-CI + dispatch + nightly cron (cron value <code>7 5 * * *</code> lifted from e2e.yml).</li><li><code>.github/workflows/preview.yml</code>: <code>workflow_run: workflows: [&#39;e2e&#39;]</code> → <code>workflow_run: workflows: [&#39;docker-e2e&#39;]</code>.</li><li><code>README.md</code>: badge URL points at docker-e2e.yml instead of e2e.yml.</li><li><code>AGENTS.md</code>: workflow listing drops <code>e2e.yml</code>; chain reference <code>ci.yml → e2e.yml → preview.yml</code> updates to <code>ci.yml → docker-e2e.yml → preview.yml</code>.</li></ul><p>ADR-066&#39;s &quot;Trigger surface&quot; + &quot;Why desktop-chromium only&quot; + &quot;Relationship to existing workflows&quot; + &quot;Branch protection&quot; sections are marked superseded by this ADR; ADR-066&#39;s core decision (docker-compose stack as the e2e validation target, Playwright env-var override, webServer short-circuit) continues to apply.</p>`,53)])])}const g=s(o,[["render",n]]);export{k as __pageData,g as default};
